const SITE_ASSETS: Readonly<Record<string, AssetEntry>> = MANIFEST.assets

// The <global:asset> namespace binding. `get` throws on an unknown path (misspellings fail at the call site
// instead of producing a broken URL), matching asset.ts's getSiteAssetPath; `tryGet` / `entry` return null.
export const asset = {
  // Resolve a logical asset path (`/CrowMark.otf`) to its current hashed URL. Throws if missing.
  get(logicalPath: string): string {
    const entry = SITE_ASSETS[logicalPath]
    if (!entry) {
      throw new Error(`Unknown site asset: ${logicalPath}`)
    }
    return entry.link
  },

  // Resolve safely -- null if the asset is missing rather than throwing.
  tryGet(logicalPath: string): string | null {
    return SITE_ASSETS[logicalPath]?.link ?? null
  },

  // The full entry (link + code + hash + size), or null.
  entry(logicalPath: string): AssetEntry | null {
    return SITE_ASSETS[logicalPath] ?? null
  },

  // The bare `assets` table, for direct iteration.
  all(): Readonly<Record<string, AssetEntry>> {
    return SITE_ASSETS
  },

  // The full manifest, for advanced callers.
  manifest(): AssetsManifest {
    return MANIFEST
  },
}
